#!/usr/bin/env node
// Save this file as install-improvements.mjs in CultureFlow-New root, then:
//   node install-improvements.mjs
import fs from 'fs';
import path from 'path';

const files = [{"path": ".gitignore", "b64": ""}, {"path": "APPLY.md", "b64": ""}, {"path": "README.md", "b64": ""}, {"path": "docs/BUILD_POLICY.md", "b64": ""}, {"path": "docs/REGION_VENUE_POLICY.md", "b64": ""}, {"path": "docs/SCRAPER_STABILITY.md", "b64": ""}, {"path": "scripts/cleanup-repo-junk.sh", "b64": ""}, {"path": "scripts/fix-region-mismatches.ts", "b64": ""}, {"path": "scripts/report-scraper-health.ts", "b64": ""}, {"path": "scripts/utils/scraper-runner.ts", "b64": ""}, {"path": "scripts/utils/scraper-utils.ts", "b64": ""}, {"path": "src/lib/region-normalize.ts", "b64": ""}, {"path": "src/types.ts", "b64": ""}];


const root = process.cwd();
let n = 0;
for (const f of files) {
  const full = path.join(root, f.path);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, Buffer.from(f.b64, 'base64'));
  console.log('wrote', f.path);
  n++;
}
// package.json name patch
const pkgPath = path.join(root, 'package.json');
if (fs.existsSync(pkgPath)) {
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
  if (pkg.name === 'thermal-hypernova') {
    pkg.name = 'culture-flow';
    if (!pkg.scripts) pkg.scripts = {};
    pkg.scripts['report:health'] = 'npx tsx scripts/report-scraper-health.ts';
    pkg.scripts['fix:regions'] = 'npx tsx scripts/fix-region-mismatches.ts';
    pkg.scripts['fix:regions:write'] = 'npx tsx scripts/fix-region-mismatches.ts --write';
    pkg.scripts['cleanup:junk'] = 'bash scripts/cleanup-repo-junk.sh';
    fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
    console.log('patched package.json name -> culture-flow (+ scripts)');
  } else {
    console.log('package.json name is', pkg.name, '- skipped rename');
  }
}
console.log('Done:', n, 'files');
console.log('');
console.log('Next commands:');
console.log('  chmod +x scripts/cleanup-repo-junk.sh && ./scripts/cleanup-repo-junk.sh');
console.log('  npx tsx scripts/fix-region-mismatches.ts --write');
console.log('  npx tsx scripts/report-scraper-health.ts');
console.log('  git add -A && git status');
